  $lingjson${"slug": "linguistics-history-of-the-english-language", "title": "Linguistics / History of the English Language", "description": "Linguistics / History of the English Language introduces students to the structure, development, variation, and cultural politics of English. Students study phonetics, phonology, morphology, syntax, semantics, pragmatics, historical linguistics, Old English, Middle English, Early Modern English, modern standardization, World Englishes, dialects, sociolinguistics, writing systems, stylistics, and language-history research methods.", "topics": [{"id": "f7683ec9-5849-4f08-98f4-0f0881353076", "type": "topic", "title": "Language Study, English Studies, and Linguistic Method", "description": "This opening unit frames linguistics as a scientific and humanistic approach to English: how language works, changes, varies, and carries cultural meaning.", "children": [{"id": "5cfe5471-5644-47c3-94f6-3891135b398c", "type": "subtopic", "title": "Descriptive versus prescriptive grammar", "children": [{"id": "453c163f-da12-4245-b3a2-a1483d289b3a", "type": "concept", "title": "descriptivism"}, {"id": "079fd345-e621-4caa-9cbc-69ba981027fc", "type": "concept", "title": "prescriptivism"}, {"id": "042194da-f3e7-4f72-a35d-378f625e0068", "type": "concept", "title": "standard language ideology"}, {"id": "1199c461-c220-447d-8ad5-d410b1bda392", "type": "concept", "title": "usage guide"}, {"id": "d27bea12-1146-4f1b-8956-99add0c0a009", "type": "concept", "title": "grammar myth"}, {"id": "72bee1e6-7f0c-488c-92ca-c0f60466ea12", "type": "concept", "title": "language attitude"}], "description": "Students learn to distinguish how people actually use language from social rules about how people are told they should use it."}, {"id": "258cdf18-cd34-49eb-be8a-47659e111202", "type": "subtopic", "title": "Levels of linguistic analysis", "children": [{"id": "2c1faeff-ba5f-467b-97c1-505a4762fbef", "type": "concept", "title": "phonetics"}, {"id": "29275e35-75d9-4520-bda1-9b201c9353ef", "type": "concept", "title": "phonology"}, {"id": "b38a5fd2-a3f6-42c2-80d8-98222ed5d04a", "type": "concept", "title": "morphology"}, {"id": "42cc2af5-e13d-4ba2-85dd-020c6aafe1d4", "type": "concept", "title": "syntax"}, {"id": "44a4e183-6a37-46ed-8438-c1734d245f19", "type": "concept", "title": "semantics"}, {"id": "b1c0d1de-b5a0-401b-bd09-546e68290840", "type": "concept", "title": "pragmatics"}], "description": "This subtopic introduces the major components of language structure that organize the course."}, {"id": "67cab9e3-28c7-4e99-b86f-e24ddc645d4d", "type": "subtopic", "title": "Evidence and data in language study", "children": [{"id": "93a367fc-7a76-41d3-9062-36f87026c826", "type": "concept", "title": "corpus"}, {"id": "af539713-5000-4cc5-a4c2-71fe66efe00e", "type": "concept", "title": "elicitation"}, {"id": "da623025-4b56-440b-9cc1-6b375362efca", "type": "concept", "title": "attested form"}, {"id": "4cf5edac-7d0c-4b56-a852-6949897ca33a", "type": "concept", "title": "speaker intuition"}, {"id": "2e9d82b6-88ee-4316-a2d4-ec21dc1becc5", "type": "concept", "title": "minimal pair"}, {"id": "6f229d62-aec4-495f-9eba-1c317f0fab5a", "type": "concept", "title": "historical citation"}], "description": "Students learn how linguists use examples, corpora, dictionaries, field notes, historical texts, and speaker judgments."}]}, {"id": "9fdbfdc3-b962-4f15-a08e-7f42a612aa82", "type": "topic", "title": "Phonetics and Phonology", "description": "This unit studies the sound system of English, from physical speech production to the abstract sound patterns speakers recognize.", "children": [{"id": "6a9ea2ac-c1d3-4f6c-906e-41e64bb3248f", "type": "subtopic", "title": "Articulatory phonetics", "children": [{"id": "34106cac-e61f-40f2-85d3-5cf037d39339", "type": "concept", "title": "IPA"}, {"id": "97848434-8c2d-4f9a-b547-985c9dd06bc7", "type": "concept", "title": "place of articulation"}, {"id": "fcd71bd7-52b3-4d9d-91f3-63d95e96c97a", "type": "concept", "title": "manner of articulation"}, {"id": "13af8f95-a1b3-4cd3-838d-c40bd20a35a8", "type": "concept", "title": "voicing"}, {"id": "5665adf2-b25c-4cdf-a026-df711982ce93", "type": "concept", "title": "vowel height"}, {"id": "8cfd5ae9-25c5-4f09-8d6c-c17109fada5a", "type": "concept", "title": "vowel backness"}], "description": "Students learn how speech sounds are produced and described using place, manner, voicing, and vowel quality."}, {"id": "a05a60e1-c4aa-41b9-a111-fb42a839ad61", "type": "subtopic", "title": "Phonemes and sound patterns", "children": [{"id": "b02c94ad-2128-4a68-b4fa-1ea93c06761f", "type": "concept", "title": "phoneme"}, {"id": "1061e4f0-9f08-4e26-bc9b-c2bdfe9119b0", "type": "concept", "title": "allophone"}, {"id": "aebaed37-04f0-43e7-8807-3f13196c8120", "type": "concept", "title": "minimal pair"}, {"id": "c043b01e-713d-4841-8bfe-6c6e31bdcd1a", "type": "concept", "title": "complementary distribution"}, {"id": "d08c27e7-158c-4582-ab71-d9700eeee888", "type": "concept", "title": "free variation"}, {"id": "8f276425-be0f-48df-a0d5-e46a7c2de481", "type": "concept", "title": "phonotactics"}], "description": "This subtopic explains how English organizes sounds into contrastive categories and predictable variants."}, {"id": "ce53d8b8-dcb1-4166-829d-aaf156688945", "type": "subtopic", "title": "English sound change and accents", "children": [{"id": "d59d0978-fd09-4304-a7dc-89c0bc8c9988", "type": "concept", "title": "Great Vowel Shift"}, {"id": "bdc0e367-1de2-4de7-a5de-b9f39a227414", "type": "concept", "title": "rhoticity"}, {"id": "81cd4687-9b47-448f-836a-e170b1a31793", "type": "concept", "title": "cot-caught merger"}, {"id": "be1164bb-53c5-4666-af81-7a531bd523a9", "type": "concept", "title": "vowel shift"}, {"id": "91284218-7336-4a8d-9af1-713df85b2458", "type": "concept", "title": "stress"}, {"id": "018da0ba-1356-4bfc-b133-8292966dccf6", "type": "concept", "title": "intonation"}], "description": "Students connect sound systems to historical shifts and contemporary accents."}]}, {"id": "a48a4fd5-2052-4263-a967-76c1ca4fc133", "type": "topic", "title": "Morphology and Word Formation", "description": "Morphology studies how words are built. This unit helps students see English vocabulary as a structured system with historical layers.", "children": [{"id": "009ec75f-949c-4686-bcbf-df110dd840ad", "type": "subtopic", "title": "Morphemes and word structure", "children": [{"id": "43e8851c-e0d7-43ca-897b-e0dec1376438", "type": "concept", "title": "morpheme"}, {"id": "3a68adf4-4aca-422d-ae42-9c5b546ac364", "type": "concept", "title": "root"}, {"id": "71d4285b-86a6-41cd-ab50-a77d68dfe708", "type": "concept", "title": "prefix"}, {"id": "54db800b-faf5-46a2-b406-50b1fda64844", "type": "concept", "title": "suffix"}, {"id": "a7a3f002-924f-47cf-9670-e6dcbf2acad5", "type": "concept", "title": "inflection"}, {"id": "3fb78d73-8655-4617-a4e2-3a379b0654e5", "type": "concept", "title": "derivation"}], "description": "Students identify roots, affixes, inflection, derivation, and compounds in English words."}, {"id": "306911ef-6325-4c64-8476-0d3b370895d4", "type": "subtopic", "title": "Productivity and word creation", "children": [{"id": "ddd3e101-ccef-46b9-a866-10211ed55ae1", "type": "concept", "title": "compounding"}, {"id": "782db0d6-c682-4569-8838-50d00e3771db", "type": "concept", "title": "conversion"}, {"id": "17c18bed-7318-4210-8432-55cfd438681e", "type": "concept", "title": "blending"}, {"id": "7f7bb2b3-5c4f-4a67-a199-d3cffb327ddc", "type": "concept", "title": "clipping"}, {"id": "68294d49-af41-4277-963c-fbbbacec5086", "type": "concept", "title": "acronym"}, {"id": "8085d48a-67c4-4f11-b2f2-7312bb93c53a", "type": "concept", "title": "back-formation"}], "description": "This subtopic examines how new English words enter use through rule-governed and creative processes."}, {"id": "c0b62491-ad53-407d-bc6c-ff00731399a6", "type": "subtopic", "title": "Borrowing and lexical strata", "children": [{"id": "7705ceeb-f90c-4d46-a3ca-2070c2d70522", "type": "concept", "title": "loanword"}, {"id": "0d208a6d-0366-48dd-b81a-1fb7c438d709", "type": "concept", "title": "cognate"}, {"id": "fa7e3193-7b70-4737-942e-0302b42c41e6", "type": "concept", "title": "etymology"}, {"id": "e6a6434e-d71a-4983-afb5-2ab7797ce102", "type": "concept", "title": "doublet"}, {"id": "18f6732f-a67b-4424-82bc-ed7cc9698a84", "type": "concept", "title": "Anglo-Saxon"}, {"id": "bd8cc578-cfcb-4aaf-a172-86937fc2d152", "type": "concept", "title": "Latinate vocabulary"}], "description": "Students learn how Old English, Norse, French, Latin, Greek, and global borrowings shape English vocabulary."}]}, {"id": "150de1cd-fa39-4775-802d-d5618dd5fd7c", "type": "topic", "title": "Syntax and English Sentence Structure", "description": "Syntax explains how words combine into phrases and sentences. Students learn the grammar beneath familiar prose, speech, and literary style.", "children": [{"id": "3da916b4-5c07-404b-86ff-f2df45895766", "type": "subtopic", "title": "Phrases, clauses, and constituency", "children": [{"id": "aaa15603-e7c9-431e-b25b-454e23ad1f03", "type": "concept", "title": "noun phrase"}, {"id": "33aaa441-089a-40cd-8700-3e00e1df0111", "type": "concept", "title": "verb phrase"}, {"id": "218e4ea6-78c0-4570-8338-65ca43aeb355", "type": "concept", "title": "prepositional phrase"}, {"id": "5ef65221-59e1-42a1-8592-31f417cae931", "type": "concept", "title": "clause"}, {"id": "e34a9ccf-3628-43d8-8e9c-6d8b1e66a612", "type": "concept", "title": "constituency"}, {"id": "f044148e-2145-4f58-acce-7dd8fcb6ce77", "type": "concept", "title": "tree diagram"}], "description": "Students practice identifying the structural units that make English sentences interpretable."}, {"id": "b9ef706b-641c-408d-9e9d-74360544061e", "type": "subtopic", "title": "English word order and grammar", "children": [{"id": "48c9402a-69de-4d1c-b70b-efb3f3f0765b", "type": "concept", "title": "SVO order"}, {"id": "f7817cc0-2d5b-42ac-8efe-2dceeb1b1487", "type": "concept", "title": "auxiliary"}, {"id": "e8a744e2-