-b270-607772e5df8b", "type": "concept", "title": "synonymy"}, {"id": "6a9c60bc-d276-4fcf-856a-5a30d4d31816", "type": "concept", "title": "semantic field"}], "description": "Students learn relationships among word meanings and how meanings shift over time."}, {"id": "338a1e07-db42-4352-9ea4-7f17443d3dba", "type": "subtopic", "title": "Sentence meaning and logic", "children": [{"id": "6d148b3e-a276-4b92-b555-23c900e1604e", "type": "concept", "title": "reference"}, {"id": "c9da311a-1cdf-4df7-96f2-f0d194a0cac0", "type": "concept", "title": "sense"}, {"id": "eb1124a6-304e-479e-92b7-484692a41770", "type": "concept", "title": "entailment"}, {"id": "20113a3c-e3a0-40d2-977f-f62f8cc408c3", "type": "concept", "title": "presupposition"}, {"id": "9353b929-2bb8-4707-9c0c-5aaf998efdb0", "type": "concept", "title": "scope ambiguity"}, {"id": "b9947f19-66b9-4095-aefb-9f7013a351c5", "type": "concept", "title": "deixis"}], "description": "This subtopic introduces basic tools for analyzing truth, reference, entailment, and ambiguity."}, {"id": "c8f84f33-b8f0-417d-888a-425735dd0106", "type": "subtopic", "title": "Pragmatic meaning in context", "children": [{"id": "cfd931e1-1834-42fe-ac3f-951ee07c18b4", "type": "concept", "title": "speech act"}, {"id": "f9c9d25c-525d-44cf-8925-013df68bf32f", "type": "concept", "title": "implicature"}, {"id": "39f8cadf-ae04-40ef-a061-876431bee8b3", "type": "concept", "title": "Gricean maxims"}, {"id": "c81f40b9-29ba-4fdb-9480-d15e331731ea", "type": "concept", "title": "politeness"}, {"id": "59ac5af2-f675-4e81-8356-ad0ea1b31f67", "type": "concept", "title": "context"}, {"id": "ce508673-7430-43a7-b204-6db09176aef7", "type": "concept", "title": "indexicality"}], "description": "Students study how speakers do things with language beyond literal meaning."}]}, {"id": "3f3171df-a1a4-41a2-990e-40a86e74c1b3", "type": "topic", "title": "Historical Linguistics and Language Change", "description": "Historical linguistics explains how languages change over time and how scholars reconstruct earlier forms from evidence.", "children": [{"id": "f4111f56-1dda-47a6-901b-b5689e09f1f2", "type": "subtopic", "title": "Mechanisms of language change", "children": [{"id": "4cb6037b-e6e2-4f10-82b9-aa6fdf17542d", "type": "concept", "title": "sound change"}, {"id": "973c5cc5-ed35-4dfc-aae6-7f087631c224", "type": "concept", "title": "semantic change"}, {"id": "23184ef6-ceec-46ab-9777-dfbe71749c3b", "type": "concept", "title": "analogical change"}, {"id": "f9dc2c33-2e3b-489f-825a-83f7aa8a52a4", "type": "concept", "title": "grammaticalization"}, {"id": "3f3f5ca6-a65f-4411-a798-6c12a51b6e57", "type": "concept", "title": "reanalysis"}, {"id": "604a368d-2755-4ced-9220-2d85f0cc9bd2", "type": "concept", "title": "lexical diffusion"}], "description": "Students learn how sounds, words, grammar, and meanings shift across generations."}, {"id": "b46f376e-3bd5-4531-ae07-507b268493f7", "type": "subtopic", "title": "Comparative method", "children": [{"id": "242fbce9-abcd-41e0-9291-17ecb78c82b2", "type": "concept", "title": "comparative method"}, {"id": "09251272-c9df-4b8b-85f7-19b00154fcee", "type": "concept", "title": "sound correspondence"}, {"id": "01088031-8425-4e3f-86de-42a821b6816f", "type": "concept", "title": "proto-language"}, {"id": "a0745697-b3b3-4bb4-b146-1f1560d53299", "type": "concept", "title": "cognate set"}, {"id": "119ef484-3758-4cf8-928b-a2fad29ef5f1", "type": "concept", "title": "reconstruction"}, {"id": "9def2e18-e290-4ceb-8b92-9a26e284afa6", "type": "concept", "title": "family tree"}], "description": "This subtopic introduces how linguists establish language relationships and reconstruct earlier forms."}, {"id": "0cf2a40c-2178-4475-86ee-0596160b5c75", "type": "subtopic", "title": "Contact and change", "children": [{"id": "44c6d1ff-e6ad-4322-bb6b-6ac463b006ec", "type": "concept", "title": "language contact"}, {"id": "2851c09b-4aaf-4c16-9811-85ecf23aa25a", "type": "concept", "title": "substrate"}, {"id": "911618e9-8971-4454-a082-77e0d1e878c2", "type": "concept", "title": "superstrate"}, {"id": "d2fcc2f2-43ae-4900-b1c2-12f4fff8312d", "type": "concept", "title": "borrowing"}, {"id": "f2f63277-a44b-4999-81a9-ca772bbcf1d1", "type": "concept", "title": "code-switching"}, {"id": "b1d0f352-f5ee-477d-9953-e0111b2a4ed3", "type": "concept", "title": "pidgin / creole"}], "description": "Students examine how conquest, migration, trade, colonization, and multilingualism shape English."}]}, {"id": "9266c6ee-47f3-460d-a5f9-3032f775699b", "type": "topic", "title": "Indo-European, Germanic, and the Origins of English", "description": "This unit situates English within the Indo-European and Germanic language families before turning to Old English.", "children": [{"id": "35d2d14d-6bf3-449f-974e-56d51d6204a0", "type": "subtopic", "title": "Indo-European background", "children": [{"id": "1b55c65d-badc-4bc2-8322-299ba878c29f", "type": "concept", "title": "Indo-European"}, {"id": "894b26ed-865e-408a-bdcd-fb72c20dd088", "type": "concept", "title": "Proto-Indo-European"}, {"id": "896f58d3-17ec-40f5-ae1e-67fcbbb423d5", "type": "concept", "title": "cognate"}, {"id": "cac99655-9e6b-4ed9-8f71-ca2453a06448", "type": "concept", "title": "Grimm's Law"}, {"id": "8dbed60d-6438-4cea-bd27-bdc6b76406fa", "type": "concept", "title": "ablaut"}, {"id": "8d874ecb-f2da-4faa-a31b-e67c25faf069", "type": "concept", "title": "family tree"}], "description": "Students learn the broad historical family that links English to many European and South Asian languages."}, {"id": "4cdd48c7-d811-422d-b067-23a2900e8bbe", "type": "subtopic", "title": "Germanic inheritance", "children": [{"id": "d26d7e1b-ddb0-4827-b30a-6b80042d9a69", "type": "concept", "title": "Proto-Germanic"}, {"id": "51064ebb-8a29-44e3-bb9b-b51885079d39", "type": "concept", "title": "West Germanic"}, {"id": "84fa5f8d-82e5-4a1a-a6b9-33f00a459ef4", "type": "concept", "title": "strong verb"}, {"id": "92bb35a6-a6bc-4567-b5e3-2eca4af1fe94", "type": "concept", "title": "weak verb"}, {"id": "19