set
  title = 'Linguistics / History of the English Language',
  goal = 'Linguistics / History of the English Language',
  summary = 'Linguistics / History of the English Language introduces students to the structure, development, variation, and cultural politics of English. Students study phonetics, phonology, morphology, syntax, semantics, pragmatics, historical linguistics, Old English, Middle English, Early Modern English, modern standardization, World Englishes, dialects, sociolinguistics, writing systems, stylistics, and language-history research methods.',
  data = $lingjson${"slug": "linguistics-history-of-the-english-language", "title": "Linguistics / History of the English Language", "description": "Linguistics / History of the English Language introduces students to the structure, development, variation, and cultural politics of English. Students study phonetics, phonology, morphology, syntax, semantics, pragmatics, historical linguistics, Old English, Middle English, Early Modern English, modern standardization, World Englishes, dialects, sociolinguistics, writing systems, stylistics, and language-history research methods.", "topics": [{"id": "f7683ec9-5849-4f08-98f4-0f0881353076", "type": "topic", "title": "Language Study, English Studies, and Linguistic Method", "description": "This opening unit frames linguistics as a scientific and humanistic approach to English: how language works, changes, varies, and carries cultural meaning.", "children": [{"id": "5cfe5471-5644-47c3-94f6-3891135b398c", "type": "subtopic", "title": "Descriptive versus prescriptive grammar", "children": [{"id": "453c163f-da12-4245-b3a2-a1483d289b3a", "type": "concept", "title": "descriptivism"}, {"id": "079fd345-e621-4caa-9cbc-69ba981027fc", "type": "concept", "title": "prescriptivism"}, {"id": "042194da-f3e7-4f72-a35d-378f625e0068", "type": "concept", "title": "standard language ideology"}, {"id": "1199c461-c220-447d-8ad5-d410b1bda392", "type": "concept", "title": "usage guide"}, {"id": "d27bea12-1146-4f1b-8956-99add0c0a009", "type": "concept", "title": "grammar myth"}, {"id": "72bee1e6-7f0c-488c-92ca-c0f60466ea12", "type": "concept", "title": "language attitude"}], "description": "Students learn to distinguish how people actually use language from social rules about how people are told they should use it."}, {"id": "258cdf18-cd34-49eb-be8a-47659e111202", "type": "subtopic", "title": "Levels of linguistic analysis", "children": [{"id": "2c1faeff-ba5f-467b-97c1-505a4762fbef", "type": "concept", "title": "phonetics"}, {"id": "29275e35-75d9-4520-bda1-9b201c9353ef", "type": "concept", "title": "phonology"}, {"id": "b38a5fd2-a3f6-42c2-80d8-98222ed5d04a", "type": "concept", "title": "morphology"}, {"id": "42cc2af5-e13d-4ba2-85dd-020c6aafe1d4", "type": "concept", "title": "syntax"}, {"id": "44a4e183-6a37-46ed-8438-c1734d245f19", "type": "concept", "title": "semantics"}, {"id": "b1c0d1de-b5a0-401b-bd09-546e68290840", "type": "concept", "title": "pragmatics"}], "description": "This subtopic introduces the major components of language structure that organize the course."}, {"id": "67cab9e3-28c7-4e99-b86f-e24ddc645d4d", "type": "subtopic", "title": "Evidence and data in language study", "children": [{"id": "93a367fc-7a76-41d3-9062-36f87026c826", "type": "concept", "title": "corpus"}, {"id": "af539713-5000-4cc5-a4c2-71fe66efe00e", "type": "concept", "title": "elicitation"}, {"id": "da623025-4b56-440b-9cc1-6b375362efca", "type": "concept", "title": "attested form"}, {"id": "4cf5edac-7d0c-4b56-a852-6949897ca33a", "type": "concept", "title": "speaker intuition"}, {"id": "2e9d82b6-88ee-4316-a2d4-ec21dc1becc5", "type": "concept", "title": "minimal pair"}, {"id": "6f229d62-aec4-495f-9eba-1c317f0fab5a", "type": "concept", "title": "historical citation"}], "description": "Students learn how linguists use examples, corpora, dictionaries, field notes, historical texts, and speaker judgments."}]}, {"id": "9fdbfdc3-b962-4f15-a08e-7f42a612aa82", "type": "topic", "title": "Phonetics and Phonology", "description": "This unit studies the sound system of English, from physical speech production to the abstract sound patterns speakers recognize.", "children": [{"id": "6a9ea2ac-c1d3-4f6c-906e-41e64bb3248f", "type": "subtopic", "title": "Articulatory phonetics", "children": [{"id": "34106cac-e61f-40f2-85d3-5cf037d39339", "type": "concept", "title": "IPA"}, {"id": "97848434-8c2d-4f9a-b547-985c9dd06bc7", "type": "concept", "title": "place of articulation"}, {"id": "fcd71bd7-52b3-4d9d-91f3-63d95e96c97a", "type": "concept", "title": "manner of articulation"}, {"id": "13af8f95-a1b3-4cd3-838d-c40bd20a35a8", "type": "concept", "title": "voicing"}, {"id": "5665adf2-b25c-4cdf-a026-df711982ce93", "type": "concept", "title": "vowel height"}, {"id": "8cfd5ae9-25c5-4f09-8d6c-c17109fada5a", "type": "concept", "title": "vowel backness"}], "description": "Students learn how speech sounds are produced and described using place, manner, voicing, and vowel quality."}, {"id": "a05a60e1-c4aa-41b9-a111-fb42a839ad61", "type": "subtopic", "title": "Phonemes and sound patterns", "children": [{"id": "b02c94ad-2128-4a68-b4fa-1ea93c06761f", "type": "concept", "title": "phoneme"}, {"id": "1061e4f0-9f08-4e26-bc9b-c2bdfe9119b0", "type": "concept", "title": "allophone"}, {"id": "aebaed37-04f0-43e7-8807-3f13196c8120", "type": "concept", "title": "minimal pair"}, {"id": "c043b01e-713d-4841-8bfe-6c6e31bdcd1a", "type": "concept", "title": "complementary distribution"}, {"id": "d08c27e7-158c-4582-ab71-d9700eeee888", "type": "concept", "title": "free variation"}, {"id": "8f276425-be0f-48df-a0d5-e46a7c2de481", "type": "concept", "title": "phonotactics"}], "description": "This subtopic explains how English organizes sounds into contrastive categories and predictable variants."}, {"id": "ce53d8b8-dcb1-4166-829d-aaf156688945", "type": "subtopic", "title": "English sound change and accents", "children": [{"id": "d59d0978-fd09-4304-a7dc-89c0bc8c9988", "type": "concept", "title": "Great Vowel Shift"}, {"id": "bdc0e367-1de2-4de7-a5de-b9f39a227414", "type": "concept", "title": "rhoticity"}, {"id": "81cd4687-9b47-448f-836a-e170b1a31793", "type": "concept", "title": "cot-caught merger"}, {"id": "be1164bb-53c5-4666-af81-7a531bd523a9", "type": "concept", "title": "vowel shift"}, {"id": "91284218-7336-4a8d-9af1-713df85b2458", "type": "concept", "title": "stress"}, {"id": "018da0ba-1356-4bfc-b133-8292966dccf6", "type": "concept", "title": "intonation"}], "description": "Students connect sound systems to historical shifts and contemporary accents."}]}, {"id": "a48a4fd5-2052-4263-a967-76c1ca4fc133", "type": "topic", "title": "Morphology and Word Formation", "description": "Morphology studies how words are built. This unit helps students see English vocabulary as a structured system with historical layers.", "children": [{"id": "009ec75f-949c-4686-bcbf-df110dd840ad", "type": "subtopic", "title": "Morphemes and word structure", "children": [{"id": "43e8851c-e0d7-43ca-897b-e0dec1376438", "type": "concept", "title": "morpheme"}, {"id": "3a68adf4-4aca-422d-ae42-9c5b546ac364", "type": "concept", "title": "root"}, {"id": "71d4285b-86a6-41cd-ab50-a77d68dfe708", "type": "concept", "title": "prefix"}, {"id": "54db800b-faf5-46a2-b406-50b1fda64844", "type": "concept", "title": "suffix"}, {"id": "a7a3f002-924f-47cf-9670-e6dcbf2acad5", "type": "concept", "title": "inflection"}, {"id": "3fb78d73-8655-4617-a4e2-3a379b0654e5", "type": "concept", "title": "derivation"}], "description": "Students identify roots, affixes, inflection, derivation, and compounds in English words."}, {"id": "306911ef-6325-4c64-8476-0d3b370895d4", "type": "subtopic", "title": "Productivity and word creation", "children": [{"id": "ddd3e101-ccef-46b9-a866-10211ed55ae1", "type": "concept", "title": "compounding"}, {"id": "782db0d6-c682-4569-8838-50d00e3771db", "type": "concept", "title": "conversion"}, {"id": "17c18bed-7318-4210-8432-55cfd438681e", "type": "concept", "title": "blending"}, {"id": "7f7bb2b3-5c4f-4a67-a199-d3cffb327ddc", "type": "concept", "title": "clipping"}, {"id": "68294d49-af41-4277-963c-fbbbacec5086", "type": "concept", "title": "acronym"}, {"id": "8085d48a-67c4-4f11-b2f2-7312bb93c53a", "type": "concept", "title": "back-formation"}], "description": "This subtopic examines how new English words enter use through rule-governed and creative processes."}, {"id": "c0b62491-ad53-407d-bc6c-ff00731399a6", "type": "subtopic", "title": "Borrowing and lexical strata", "children": [{"id": "7705ceeb-f90c-4d46-a3ca-2070c2d70522", "type": "concept", "title": "loanword"}, {"id": "0d208a6d-0366-48dd-b81a-1fb7c438d709", "type": "concept", "title": "cognate"}, {"id": "fa7e3193-7b70-4737-942e-0302b42c41e6", "type": "concept", "title": "etymology"}, {"id": "e6a6434e-d71a-4983-afb5-2ab7797ce102", "type": "concept", "title": "doublet"}, {"id": "18f6732f-a67b-4424-82bc-ed7cc9698a84", "type": "concept", "title": "Anglo-Saxon"}, {"id": "bd8cc578-cfcb-4aaf-a172-86937fc2d152", "type": "concept", "title": "Latinate vocabulary"}], "description": "Students learn how Old English, Norse, French, Latin, Greek, and global borrowings shape English vocabulary."}]}, {"id": "150de1cd-fa39-4775-802d-d5618dd5fd7c", "type": "topic", "title": "Syntax and English Sentence Structure", "description": "Syntax explains how words combine into phrases and sentences. Students learn the grammar beneath familiar prose, speech, and literary style.", "children": [{"id": "3da916b4-5c07-404b-86ff-f2df45895766", "type": "subtopic", "title": "Phrases, clauses, and constituency", "children": [{"id": "aaa15603-e7c9-431e-b25b-454e23ad1f03", "type": "concept", "title": "noun phrase"}, {"id": "33aaa441-089a-40cd-8700-3e00e1df0111", "type": "concept", "title": "verb phrase"}, {"id": "218e4ea6-78c0-4570-8338-65ca43aeb355", "type": "concept", "title": "prepositional phrase"}, {"id": "5ef65221-59e1-42a1-8592-31f417cae931", "type": "concept", "title": "clause"}, {"id": "e34a9ccf-3628-43d8-8e9c-6d8b1e66a612", "type": "concept", "title": "constituency"}, {"id": "f044148e-2145-4f58-acce-7dd8fcb6ce77", "type": "concept", "title": "tree diagram"}], "description": "Students practice identifying the structural units that make English sentences interpretable."}, {"id": "b9ef706b-641c-408d-9e9d-74360544061e", "type": "subtopic", "title": "English word order and grammar", "children": [{"id": "48c9402a-69de-4d1c-b70b-efb3f3f0765b", "type": "concept", "title": "SVO order"}, {"id": "f7817cc0-2d5b-42ac-8efe-2dceeb1b1487", "type": "concept", "title": "auxiliary"}, {"id": "e8a744e2-b69b-4b03-bde9-7f459106529e", "type": "concept", "title": "tense"}, {"id": "69de63f2-f88f-474a-a047-fce8256075d7", "type": "concept", "title": "agreement"}, {"id": "53692ee2-3646-4c6c-8c8e-c3f60f82569c", "type": "concept", "title": "subordination"}, {"id": "cd6297ae-f8a1-4f9c-b811-fe3934b3268c", "type": "concept", "title": "complementation"}], "description": "This subtopic explains how English uses word order, auxiliaries, tense, agreement, and complementation."}, {"id": "b6b3053a-8a5e-4a23-a290-3fd14dab2457", "type": "subtopic", "title": "Syntactic variation and change", "children": [{"id": "0925e882-f55f-4a49-b319-543033de37d5", "type": "concept", "title": "negative concord"}, {"id": "1e70bd98-895d-4f4f-8bf2-433ec829d736", "type": "concept", "title": "do-support"}, {"id": "0c3daba0-1608-4377-b660-69bc5f2b4dc2", "type": "concept", "title": "relative clause"}, {"id": "d2a6ff20-7f39-462f-a673-b61deccc644a", "type": "concept", "title": "wh-movement"}, {"id": "250ab16b-0e0b-4ada-8c9e-8152b47ba737", "type": "concept", "title": "grammarization"}, {"id": "13a3aa86-7e5e-4cec-9547-5dc0496ce10b", "type": "concept", "title": "syntactic change"}], "description": "Students connect grammar to dialects, historical change, and stylistic choice."}]}, {"id": "6abd27c2-e759-43b1-979b-5f4e5d3db3ff", "type": "topic", "title": "Semantics and Pragmatics", "description": "This unit studies meaning: what words and sentences denote, what speakers imply, and how context shapes interpretation.", "children": [{"id": "ea4f06b9-3987-4b24-9ff1-6c329fe3073e", "type": "subtopic", "title": "Lexical semantics", "children": [{"id": "b30633b8-04ce-4d33-9b52-d686db9182d3", "type": "concept", "title": "denotation"}, {"id": "51fa50f8-222a-4a0f-935e-a96fea3fb3d7", "type": "concept", "title": "connotation"}, {"id": "786e84fa-fd0c-4d1b-a12d-c88838812fad", "type": "concept", "title": "polysemy"}, {"id": "24d7927a-5e44-43f1-b464-be6bfd4073bd", "type": "concept", "title": "homonymy"}, {"id": "eecef95b-48fb-40b0-b270-607772e5df8b", "type": "concept", "title": "synonymy"}, {"id": "6a9c60bc-d276-4fcf-856a-5a30d4d31816", "type": "concept", "title": "semantic field"}], "description": "Students learn relationships among word meanings and how meanings shift over time."}, {"id": "338a1e07-db42-4352-9ea4-7f17443d3dba", "type": "subtopic", "title": "Sentence meaning and logic", "children": [{"id": "6d148b3e-a276-4b92-b555-23c900e1604e", "type": "concept", "title": "reference"}, {"id": "c9da311a-1cdf-4df7-96f2-f0d194a0cac0", "type": "concept", "title": "sense"}, {"id": "eb1124a6-304e-479e-92b7-484692a41770", "type": "concept", "title": "entailment"}, {"id": "20113a3c-e3a0-40d2-977f-f62f8cc408c3", "type": "concept", "title": "presupposition"}, {"id": "9353b929-2bb8-4707-9c0c-5aaf998efdb0", "type": "concept", "title": "scope ambiguity"}, {"id": "b9947f19-66b9-4095-aefb-9f7013a351c5", "type": "concept", "title": "deixis"}], "description": "This subtopic introduces basic tools for analyzing truth, reference, entailment, and ambiguity."}, {"id": "c8f84f33-b8f0-417d-888a-425735dd0106", "type": "subtopic", "title": "Pragmatic meaning in context", "children": [{"id": "cfd931e1-1834-42fe-ac3f-951ee07c18b4", "type": "concept", "title": "speech act"}, {"id": "f9c9d25c-525d-44cf-8925-013df68bf32f", "type": "concept", "title": "implicature"}, {"id": "39f8cadf-ae04-40ef-a061-876431bee8b3", "type": "concept", "title": "Gricean maxims"}, {"id": "c81f40b9-29ba-4fdb-9480-d15e331731ea", "type": "concept", "title": "politeness"}, {"id": "59ac5af2-f675-4e81-8356-ad0ea1b31f67", "type": "concept", "title": "context"}, {"id": "ce508673-7430-43a7-b204-6db09176aef7", "type": "concept", "title": "indexicality"}], "description": "Students study how speakers do things with language beyond literal meaning."}]}, {"id": "3f3171df-a1a4-41a2-990e-40a86e74c1b3", "type": "topic", "title": "Historical Linguistics and Language Change", "description": "Historical linguistics explains how languages change over time and how scholars reconstruct earlier forms from evidence.", "children": [{"id": "f4111f56-1dda-47a6-901b-b5689e09f1f2", "type": "subtopic", "title": "Mechanisms of language change", "children": [{"id": "4cb6037b-e6e2-4f10-82b9-aa6fdf17542d", "type": "concept", "title": "sound change"}, {"id": "973c5cc5-ed35-4dfc-aae6-7f087631c224", "type": "concept", "title": "semantic change"}, {"id": "23184ef6-ceec-46ab-9777-dfbe71749c3b", "type": "concept", "title": "analogical change"}, {"id": "f9dc2c33-2e3b-489f-825a-83f7aa8a52a4", "type": "concept", "title": "grammaticalization"}, {"id": "3f3f5ca6-a65f-4411-a798-6c12a51b6e57", "type": "concept", "title": "reanalysis"}, {"id": "604a368d-2755-4ced-9220-2d85f0cc9bd2", "type": "concept", "title": "lexical diffusion"}], "description": "Students learn how sounds, words, grammar, and meanings shift across generations."}, {"id": "b46f376e-3bd5-4531-ae07-507b268493f7", "type": "subtopic", "title": "Comparative method", "children": [{"id": "242fbce9-abcd-41e0-9291-17ecb78c82b2", "type": "concept", "title": "comparative method"}, {"id": "09251272-c9df-4b8b-85f7-19b00154fcee", "type": "concept", "title": "sound correspondence"}, {"id": "01088031-8425-4e3f-86de-42a821b6816f", "type": "concept", "title": "proto-language"}, {"id": "a0745697-b3b3-4bb4-b146-1f1560d53299", "type": "concept", "title": "cognate set"}, {"id": "119ef484-3758-4cf8-928b-a2fad29ef5f1", "type": "concept", "title": "reconstruction"}, {"id": "9def2e18-e290-4ceb-8b92-9a26e284afa6", "type": "concept", "title": "family tree"}], "description": "This subtopic introduces how linguists establish language relationships and reconstruct earlier forms."}, {"id": "0cf2a40c-2178-4475-86ee-0596160b5c75", "type": "subtopic", "title": "Contact and change", "children": [{"id": "44c6d1ff-e6ad-4322-bb6b-6ac463b006ec", "type": "concept", "title": "language contact"}, {"id": "2851c09b-4aaf-4c16-9811-85ecf23aa25a", "type": "concept", "title": "substrate"}, {"id": "911618e9-8971-4454-a082-77e0d1e878c2", "type": "concept", "title": "superstrate"}, {"id": "d2fcc2f2-43ae-4900-b1c2-12f4fff8312d", "type": "concept", "title": "borrowing"}, {"id": "f2f63277-a44b-4999-81a9-ca772bbcf1d1", "type": "concept", "title": "code-switching"}, {"id": "b1d0f352-f5ee-477d-9953-e0111b2a4ed3", "type": "concept", "title": "pidgin / creole"}], "description": "Students examine how conquest, migration, trade, colonization, and multilingualism shape English."}]}, {"id": "9266c6ee-47f3-460d-a5f9-3032f775699b", "type": "topic", "title": "Indo-European, Germanic, and the Origins of English", "description": "This unit situates English within the Indo-European and Germanic language families before turning to Old English.", "children": [{"id": "35d2d14d-6bf3-449f-974e-56d51d6204a0", "type": "subtopic", "title": "Indo-European background", "children": [{"id": "1b55c65d-badc-4bc2-8322-299ba878c29f", "type": "concept", "title": "Indo-European"}, {"id": "894b26ed-865e-408a-bdcd-fb72c20dd088", "type": "concept", "title": "Proto-Indo-European"}, {"id": "896f58d3-17ec-40f5-ae1e-67fcbbb423d5", "type": "concept", "title": "cognate"}, {"id": "cac99655-9e6b-4ed9-8f71-ca2453a06448", "type": "concept", "title": "Grimm's Law"}, {"id": "8dbed60d-6438-4cea-bd27-bdc6b76406fa", "type": "concept", "title": "ablaut"}, {"id": "8d874ecb-f2da-4faa-a31b-e67c25faf069", "type": "concept", "title": "family tree"}], "description": "Students learn the broad historical family that links English to many European and South Asian languages."}, {"id": "4cdd48c7-d811-422d-b067-23a2900e8bbe", "type": "subtopic", "title": "Germanic inheritance", "children": [{"id": "d26d7e1b-ddb0-4827-b30a-6b80042d9a69", "type": "concept", "title": "Proto-Germanic"}, {"id": "51064ebb-8a29-44e3-bb9b-b51885079d39", "type": "concept", "title": "West Germanic"}, {"id": "84fa5f8d-82e5-4a1a-a6b9-33f00a459ef4", "type": "concept", "title": "strong verb"}, {"id": "92bb35a6-a6bc-4567-b5e3-2eca4af1fe94", "type": "concept", "title": "weak verb"}, {"id": "196d1dcf-9196-4af9-8761-c1ee0752b7bd", "type": "concept", "title": "umlaut"}, {"id": "3f9b5e91-6a61-4dd8-b098-3b9bf12e9846", "type": "concept", "title": "case system"}], "description": "This subtopic explains the sound, grammar, and vocabulary features English shares with other Germanic languages."}, {"id": "302af747-a98a-4455-83d1-41571f4638ec", "type": "subtopic", "title": "Migration and settlement", "children": [{"id": "df46c599-11c0-4963-b739-f6107e2deb0d", "type": "concept", "title": "Angles"}, {"id": "7b37bed5-664f-4d0e-a8ee-6d10882b70f2", "type": "concept", "title": "Saxons"}, {"id": "5f8a9148-d509-4ff9-b514-d36d5f70a5fd", "type": "concept", "title": "Jutes"}, {"id": "16cc0669-f17c-4bff-aee2-a29092b25fca", "type": "concept", "title": "Anglo-Saxon"}, {"id": "3cb370b1-dee0-421c-bd33-7132c0c8466f", "type": "concept", "title": "runic inscription"}, {"id": "3583dc77-ce49-4755-a431-2d02c5c85278", "type": "concept", "title": "Christianization"}], "description": "Students connect language history to Anglo-Saxon settlement, contact, and early textual evidence."}]}, {"id": "678be9d3-bb69-4f75-a157-8eb92b12eedd", "type": "topic", "title": "Old English", "description": "Old English reveals a richly inflected language with Germanic vocabulary, poetic formulas, dialects, and contact with Latin and Norse.", "children": [{"id": "4c933b78-544e-4a91-b31e-937ce81eabaf", "type": "subtopic", "title": "Old English grammar", "children": [{"id": "b8005306-e953-4944-a53d-a6ed84354d5b", "type": "concept", "title": "case"}, {"id": "f6792b90-5dba-4669-bc7f-78de8f3fc41f", "type": "concept", "title": "grammatical gender"}, {"id": "08de09f8-d2d0-41a2-b3e6-aeecae3d1097", "type": "concept", "title": "declension"}, {"id": "1d71334a-5091-4c3a-a354-415d19fe4bd1", "type": "concept", "title": "strong verb"}, {"id": "714f3dfd-b50f-4473-ba34-9161c47b0c62", "type": "concept", "title": "weak verb"}, {"id": "2ece7b1a-b7e0-4a02-a9f9-ab0ed9a40aeb", "type": "concept", "title": "word order"}], "descr